import { Document, Page, Text, View, StyleSheet } from '@react-pdf/renderer';
import HeaderPDF from './HeaderPDF';
import AnswerViewArabic from './AnswerViewArabic';
import AnswerViewLatino from './AnswerViewLatino';

const styles = StyleSheet.create({
  page: {
    padding: 15,
    display: 'flex',
    flexDirection: 'column',
    border: '2px solid black',
  },
  section: {
    paddingTop: 5,
    flexGrow: 1,
  },
  title: {
    margin:5,
    fontSize: 14,
    fontFamily: 'Amiri',
    fontWeight: 'semibold',
    marginBottom: 10,
  },
  footer: {
    position: 'absolute',
    bottom: 10, 
    left: 0,
    right: 0,
    textAlign: 'center',
    fontSize: 10,
  },
  table: {
    width: '100%',
    borderStyle: 'solid',
    borderWidth: 1,
    borderRightWidth: 0,
    borderBottomWidth: 0,
  },
  tableRow: {
    flexDirection: 'row',
  },
  tableHeader: {
    borderStyle: 'solid',
    borderWidth: 1,
    borderLeftWidth: 0,
    borderTopWidth: 0,
    paddingVertical:'auto',
  },
  tableCell: {
    padding: 5,
    borderStyle: 'solid',
    borderWidth: 1,
    borderLeftWidth: 0,
    borderTopWidth: 0,
  },
  col1: {
    width: '10%',
  },
  col2: {
    width: '10%',
  },
  col3: {
    width: '80%',
  },
});
const ExamAnswerDocument = ({ exam ,year, level, material, trimester  }) => {
  
return(
  <Document>
  <Page style={styles.page} size="A4">
    <HeaderPDF year={year} level={level} material={material} trimester={trimester} />
    {exam?.map((exercise, i) => (
      <View style={styles.table}>
        <View style={styles.tableRow}>
          <View style={[styles.tableHeader, styles.col1]}><Text>كاملة</Text></View>
          <View style={[styles.tableHeader, styles.col2]}><Text>تجزئة</Text></View>
          <View style={[styles.tableHeader, styles.col3]}>
           {exercise.rtl ? (
             <Text 
             key={`title-${exercise._id}`}
             style={[styles.title, { textAlign: 'right', direction: 'rtl' }]}>
               {`التمرين ${i + 1}:`}
             </Text>
           ) : (
             <Text 
             key={`title-${exercise._id}`}
             style={styles.title}>{`Exercise ${i + 1}:`}</Text>
           )}
          </View>
        </View>
        <View style={styles.tableRow}>
            <View style={[styles.tableCell, styles.col1]}><Text></Text></View>
            <View style={[styles.tableCell, styles.col2]}><Text></Text></View>
            <View style={[styles.tableCell, styles.col3]}>
             <View key={exercise._id} style={styles.section}>
                 {exercise?.exercise?.map((item, itemIndex) =>
                   exercise.rtl ? (
                     <AnswerViewArabic
                       key={item._id} 
                       item={item}
                       itemIndex={itemIndex}
                     />
                   ) : (
                     <AnswerViewLatino
                       key={item._id} 
                       item={item}
                       itemIndex={itemIndex}
                     />
                   )
                 )}
             </View>
            </View>
          </View>
      </View>
    ))}
    <Text
      style={styles.footer}
      render={({ pageNumber, totalPages }) => `${pageNumber} / ${totalPages}`}
      fixed
    />
  </Page>
</Document>
)};

export default ExamAnswerDocument;