import { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import Trimesters from "../../Assets/Data/Trimesters";
import difficulty from "../../Assets/Data/difficulty";
import ExerciseCard from "../../Layouts/Admin/Exercise/ExerciseCard";
import useFetchData from "../../Hooks/useFetchData";
import { Filters } from "../../Component/Filters";
import Pagination from "../../Component/Pagination";
import { useLanguage } from "../../Contexts/LanguageContext";
import { useHeader } from '../../Contexts/HeaderContext';

const Exercises = () => {
  const { t } = useLanguage();
  const { updateHeader } = useHeader();

  useEffect(() => {
    updateHeader({
      title: 'Exercises',
      buttons: (
        <Link
          to="/addExercise"
          className="btn-primary"
        >
          {t("Add_Exercise")}
        </Link>
      )
    });

    return () => updateHeader({ title: '', buttons: null });
  }, [t,updateHeader]);
  const [selectedFilters, setSelectedFilters] = useState({
    level: "All",
    trimester: "All",
    material: "All",
    unit: "All",
    difficulty: "All",
  });

  const {
    levels,
    exercises,
    setSelectedLevel,
    setSelectedMatriel,
    filteredMatriels,
    filteredUnits,
    totalPages,
    currentPage, 
    setCurrentPage,
    loading,
    error,
    refetch,
  } = useFetchData();


  const handleFilterChange = (filterType, value) => {
    setSelectedFilters((prevFilters) => ({
      ...prevFilters,
      [filterType]: value,
    }));

    // Additional updates for specific filters
    if (filterType === "level") setSelectedLevel(value);
    if (filterType === "material") setSelectedMatriel(value);
  };

  const filteredExercises = exercises.filter(
    (exercise) =>
      (selectedFilters.level === "All" ||
        exercise.level._id === selectedFilters.level) &&
      (selectedFilters.trimester === "All" ||
        exercise.Trimester === selectedFilters.trimester) &&
      (selectedFilters.material === "All" ||
        exercise.material._id === selectedFilters.material) &&
      (selectedFilters.unit === "All" ||
        exercise.unit._id === selectedFilters.unit) &&
      (selectedFilters.difficulty === "All" ||
        exercise.difficulty === selectedFilters.difficulty)
  );

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;

  return (
    <div className="container mx-auto p-4 bg-gray-100 min-h-screen">
      <Filters
        levels={levels}
        trimesters={Trimesters}
        materials={filteredMatriels}
        units={filteredUnits}
        difficulties={difficulty}
        selectedFilters={selectedFilters}
        onFilterChange={handleFilterChange}
      />
      <div className="w-full">
        {filteredExercises.map((exercise) => (
          <ExerciseCard
            key={exercise._id}
            exercise={exercise}
            RenderComponent={refetch}
          />
        ))}
      </div>
      <Pagination
        currentPage={currentPage}
        totalPages={totalPages}
        onPageChange={(page)=>setCurrentPage(page)}
      />
    </div>
  );
}
export default Exercises;