import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import api from '../../Services/api'
import { useLanguage } from '../../Contexts/LanguageContext';
const ForgotPassword = () => {
  const { t } = useLanguage();
  const [email, setEmail] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();
  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      const response=await api.post(`/api/auth/forgotPassword`, { email });
      const { message } = response.data;
      navigate('/verifyCode', { state: { email } });
    } catch (err) {
        setError(
            err.response?.data?.message || 'Something went wrong. Please try again.'
          );
        console.log(err)
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex justify-center items-center min-h-screen bg-gray-100 font-sans">
      <div className="bg-white p-8 rounded shadow-lg w-full max-w-lg">
        <h2 className="text-3xl text-center font-bold mb-2">{t("forgotPassMsg")}</h2>
        <form onSubmit={handleSubmit} className="space-y-4 flex flex-col">
          <div>
            <input
              id="email"
              type="email"
              placeholder="m@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              requiredring
              className="mt-1 mx-3 w-full input-primary"
            />
          </div>
          {error && (
            <div className="text-red-600 text-sm flex items-center gap-2">
              <span>{error}</span>
            </div>
          )}
          <button
            type="submit"
            disabled={isLoading}
            className={`${
              isLoading
                ? 'btn-primary bg-secondary cursor-not-allowed'
                : 'btn-primary'
            } w-3/4 mx-auto`}
          >
            {isLoading ? t("loadingMsg") : t("SendCode")}
          </button>
          <div className="my-2 font-semibold text-center">
          Back to Sign in page?
          <Link to='/login' className='text-primary'> {t("login")}</Link>
          </div>
        </form>
      </div>
    </div>
  );
};

export default ForgotPassword;