import ImageManager from "../../../Component/ImageManager";
import { useLanguage } from "../../../Contexts/LanguageContext";
import Switch from '@mui/material/Switch';

const positionOptions = [
  { label: 'Left', value: 'left' },
  { label: 'Right', value: 'right' },
  { label: 'Bottom', value: 'bottom' },
  { label: 'Top', value: 'top' },
];
const twoImageOptions = [
  { label: 'Bottom', value: 'bottom' },
  { label: 'Top', value: 'top' },
];

const EditExercise = ({ formData, setFormData }) => {
  const { t } = useLanguage();

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleSectionChange = (sectionIndex, field, value) => {
    setFormData(prev => ({
      ...prev,
      exercise: prev.exercise.map((section, i) => 
        i === sectionIndex ? { ...section, [field]: value } : section
      )
    }));
  };

  const handleQuestionChange = (sectionIndex, questionIndex, field, value) => {
    setFormData(prev => ({
      ...prev,
      exercise: prev.exercise.map((section, i) => {
        if (i === sectionIndex) {
          return {
            ...section,
            questions: section.questions.map((q, j) => {
              if (j === questionIndex) {
                if (field.startsWith('answer.')) {
                  const [_, answerField] = field.split('.');
                  return {
                    ...q,
                    answer: { 
                      ...q.answer, 
                      [answerField]: value 
                    }
                  };
                }
                return { ...q, [field]: value };
              }
              return q;
            })
          };
        }
        return section;
      })
    }));
  };

  const handleImageUpload = (sectionIndex, imageKey, event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        setFormData(prev => ({
          ...prev,
          exercise: prev.exercise.map((section, i) => 
            i === sectionIndex ? { ...section, [imageKey]: reader.result } : section
          )
        }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnswerImageUpload = (sectionIndex, questionIndex, imageKey, event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        setFormData(prev => ({
          ...prev,
          exercise: prev.exercise.map((section, i) => {
            if (i === sectionIndex) {
              return {
                ...section,
                questions: section.questions.map((q, j) => {
                  if (j === questionIndex) {
                    return {
                      ...q,
                      answer: { 
                        ...q.answer, 
                        [imageKey]: reader.result 
                      }
                    };
                  }
                  return q;
                })
              };
            }
            return section;
          })
        }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDeleteImage = (sectionIndex, imageKey) => {
    setFormData(prev => ({
      ...prev,
      exercise: prev.exercise.map((section, i) => 
        i === sectionIndex ? { ...section, [imageKey]: null } : section
      )
    }));
  };

  const handleDeleteAnswerImage = (sectionIndex, questionIndex, imageKey) => {
    setFormData(prev => ({
      ...prev,
      exercise: prev.exercise.map((section, i) => {
        if (i === sectionIndex) {
          return {
            ...section,
            questions: section.questions.map((q, j) => {
              if (j === questionIndex) {
                return {
                  ...q,
                  answer: { 
                    ...q.answer, 
                    [imageKey]: null 
                  }
                };
              }
              return q;
            })
          };
        }
        return section;
      })
    }));
  };

  const handleAddQuestion = (sectionIndex) => {
    setFormData(prev => ({
      ...prev,
      exercise: prev.exercise.map((section, i) => 
        i === sectionIndex ? {
          ...section,
          questions: [...section.questions, { 
            question: '', 
            answer: { 
              text: '', 
              pictureAnswerOne: null, 
              pictureAnswerTwo: null 
            }
          }]
        } : section
      )
    }));
  };

  const handleRemoveQuestion = (sectionIndex, questionIndex) => {
    setFormData(prev => ({
      ...prev,
      exercise: prev.exercise.map((section, i) => 
        i === sectionIndex ? {
          ...section,
          questions: section.questions.filter((_, j) => j !== questionIndex)
        } : section
      )
    }));
  };

  const handleAddSection = () => {
    setFormData(prev => ({
      ...prev,
      exercise: [...prev.exercise, {
        content: '',
        questions: [{ 
          question: '', 
          answer: { 
            text: '', 
            pictureAnswerOne: null, 
            pictureAnswerTwo: null 
          }
        }],
        image: null,
        secondImage: null,
        imagePosition: 'bottom'
      }]
    }));
  };

  const handleRemoveSection = (index) => {
    setFormData(prev => ({
      ...prev,
      exercise: prev.exercise.filter((_, i) => i !== index)
    }));
  };

  const exerciseDirection = formData.rtl ? "rtl" : "ltr";

  return (
    <div className="mx-8 my-10 py-8 bg-white rounded-lg">
      <form className="space-y-8">
        <div className='flex items-center justify-between'>
          <div>Arabic direction (Right to Left)</div>
          <Switch
            checked={formData.rtl}
            onChange={(e) => handleChange('rtl', e.target.checked)}
            inputProps={{ 'aria-label': 'controlled' }}
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            {t("Title")}:
          </label>
          <input
            type="text"
            value={formData.title}
            dir={exerciseDirection}
            onChange={(e) => handleChange('title', e.target.value)}
            className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
            placeholder="Enter title"
          />
        </div>

        {formData.exercise.map((section, sectionIndex) => (
          <div key={sectionIndex} className="space-y-6 rounded-lg shadow-inner p-4">
            <div>
              <h1 className="text-xl font-bold text-center">
                {t("Section")} {sectionIndex + 1}
              </h1>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                {t("Content")}:
              </label>
              <textarea
                value={section.content}
                dir={exerciseDirection}
                onChange={(e) => handleSectionChange(sectionIndex, 'content', e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
                rows="3"
                placeholder="Enter content"
              />
            </div>

            {section.questions.map((question, questionIndex) => (
              <div key={questionIndex} className="space-y-4 border-t pt-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    {t("Question")} {questionIndex + 1}:
                  </label>
                  <textarea
                    value={question.question}
                    dir={exerciseDirection}
                    onChange={(e) => handleQuestionChange(
                      sectionIndex,
                      questionIndex,
                      'question',
                      e.target.value
                    )}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
                    rows="2"
                    placeholder="Enter question"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    {t("Answer")} {questionIndex + 1}:
                  </label>
                  <textarea
                    value={question.answer.text}
                    dir={exerciseDirection}
                    onChange={(e) => handleQuestionChange(
                      sectionIndex,
                      questionIndex,
                      'answer.text',
                      e.target.value
                    )}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
                    rows="2"
                    placeholder="Enter answer text"
                  />
                  <div className="flex gap-4 mt-2">
                    <ImageManager
                      image={question.answer.pictureAnswerOne}
                      onDelete={() => handleDeleteAnswerImage(
                        sectionIndex,
                        questionIndex,
                        'pictureAnswerOne'
                      )}
                      onUpload={(e) => handleAnswerImageUpload(
                        sectionIndex,
                        questionIndex,
                        'pictureAnswerOne',
                        e
                      )}
                      label="Answer Image 1"
                    />
                    <ImageManager
                      image={question.answer.pictureAnswerTwo}
                      onDelete={() => handleDeleteAnswerImage(
                        sectionIndex,
                        questionIndex,
                        'pictureAnswerTwo'
                      )}
                      onUpload={(e) => handleAnswerImageUpload(
                        sectionIndex,
                        questionIndex,
                        'pictureAnswerTwo',
                        e
                      )}
                      label="Answer Image 2"
                    />
                  </div>
                </div>

                <button
                  type="button"
                  onClick={() => handleRemoveQuestion(sectionIndex, questionIndex)}
                  className="text-sm text-red-600 hover:text-red-800"
                >
                  {t("Remove Question")} {questionIndex + 1}
                </button>
              </div>
            ))}

            <button
              type="button"
              onClick={() => handleAddQuestion(sectionIndex)}
              className="text-sm text-blue-600 hover:text-blue-800"
            >
              {t("Add Question")} {section.questions.length + 1}
            </button>

            <div className="flex justify-center gap-4 mt-4">
              <ImageManager
                image={section.image}
                onDelete={() => handleDeleteImage(sectionIndex, 'image')}
                onUpload={(e) => handleImageUpload(sectionIndex, 'image', e)}
                label="Section Image 1"
              />
              <ImageManager
                image={section.secondImage}
                onDelete={() => handleDeleteImage(sectionIndex, 'secondImage')}
                onUpload={(e) => handleImageUpload(sectionIndex, 'secondImage', e)}
                label="Section Image 2"
              />
            </div>

            {(section.image || section.secondImage) && (
              <div className="space-y-4">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  {t("Image Position")}:
                </label>
                <select
                  value={section.imagePosition}
                  onChange={(e) => handleSectionChange(sectionIndex, 'imagePosition', e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
                >
                  {(section.image && section.secondImage)
                    ? twoImageOptions.map((option) => (
                        <option key={option.value} value={option.value}>
                          {option.label}
                        </option>
                      ))
                    : positionOptions.map((option) => (
                        <option key={option.value} value={option.value}>
                          {option.label}
                        </option>
                      ))}
                </select>
              </div>
            )}

            {sectionIndex !== 0 && (
              <button
                type="button"
                onClick={() => handleRemoveSection(sectionIndex)}
                className="text-sm text-red-600 hover:text-red-800"
              >
                {t("Remove Section")} {sectionIndex + 1}
              </button>
            )}
          </div>
        ))}

        <button
          type="button"
          onClick={handleAddSection}
          className="w-full py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-green-600 hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500"
        >
          {t("Add Section")}
        </button>
      </form>
    </div>
  );
};

export default EditExercise;