import { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import api from '../../Services/api';

export default function VerifyCode() {
  const [code, setCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [resendDisabled, setResendDisabled] = useState(false);
  const [timeLeft, setTimeLeft] = useState(300);
  const { state } = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    if (!state?.email) {
      navigate('/forgotPassword');
    }
  }, [state, navigate]);

  useEffect(() => {
    if (resendDisabled && timeLeft > 0) {
      const timer = setTimeout(() => setTimeLeft(timeLeft - 1), 1000);
      return () => clearTimeout(timer);
    } else if (timeLeft === 0) {
      setResendDisabled(false);
      setTimeLeft(60);
    }
  }, [resendDisabled, timeLeft]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('')
    try {
        const response=await api.post(`/api/auth/verifyPassResetCode`, 
           { 
            email: state.email,
            resetCode: code 
          });
        const { message } = response.data;
        navigate('/resetPassword', { state: { email: state.email } });
      } catch (err) {
          setError(
              err.response?.data?.message || 'Something went wrong. Please try again.'
            );
          console.log(err)
      } finally {
        setLoading(false);
      }
  };

  const handleResend = async () => {
    setResendDisabled(true);
    try {
        await api.post(`/api/auth/forgotPassword`, { email:state.email });
      } catch (err) {
          setError(
              err.response?.data?.message || 'Something went wrong. Please try again.'
            );
          console.log(err)
      } finally {
        setLoading(false);
      }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col justify-center py-12 sm:px-6 lg:px-8">
      <div className="sm:mx-auto sm:w-full sm:max-w-md">
        <h2 className="mt-6 text-center text-3xl font-extrabold text-gray-900">
          Verify Code
        </h2>
      </div>

      <div className="mt-8 sm:mx-auto sm:w-full sm:max-w-md">
        <div className="bg-white py-8 px-4 shadow sm:rounded-lg sm:px-10">
          <form className="space-y-6" onSubmit={handleSubmit}>
            <div>
              <label htmlFor="code" className="block text-sm font-medium text-gray-700">
                Verification Code
              </label>
              <div className="mt-1">
                <input
                  id="code"
                  name="code"
                  type="text"
                  required
                  value={code}
                  onChange={(e) => setCode(e.target.value)}
                  className="appearance-none block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm placeholder-gray-400 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                />
              </div>
            </div>

            {error && (
              <div className="text-red-500 text-sm text-center">
                {error}
              </div>
            )}

            <div>
              <button
                type="submit"
                disabled={loading}
                className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:opacity-50"
              >
                {loading ? 'Verifying...' : 'Verify Code'}
              </button>
            </div>

            <div className="text-center text-sm">
              <button
                type="button"
                onClick={handleResend}
                disabled={resendDisabled}
                className="text-indigo-600 hover:text-indigo-500 disabled:text-gray-400"
              >
                Resend Code {resendDisabled && `(${timeLeft}s)`}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}