import { Link } from 'react-router-dom';
import { ChevronRight } from 'lucide-react';
import { useLanguage } from '../../Contexts/LanguageContext';

const Setting = () => {
    const { t } = useLanguage();
    return (
      <div className="p-10 bg-gray-100">
          <div className='w-full max-w-[794px] bg-white border border-black rounded-md my-5'>
            <div className="font-semibold my-2 mx-4">
              {t('Account_Setting')}
            </div>
               <Link
                  to='/GenralInformation'
                  className="w-full bg-secondary rounded-t px-4 sm:px-8 py-4 flex justify-between items-center focus:outline-none focus:ring-2 focus:ring-gray-400"
                >
                  <span className="text-lg font-medium text-black">{t('Genral_information')}</span>
                  <ChevronRight className="h-5 w-5 text-gray-600" /> 
                </Link>
               <Link
                  to='/Security'
                  className="w-full bg-secondary rounded-b px-4 sm:px-8 py-4 flex justify-between items-center focus:outline-none focus:ring-2 focus:ring-gray-400"
                >
                  <span className="text-lg font-medium text-black">{t('Security')}</span>
                  <ChevronRight className="h-5 w-5 text-gray-600" /> 
                </Link>
          </div>
          <div className='w-full max-w-[794px] bg-white border border-black rounded-md my-5'>
            <div className="font-semibold my-2 mx-4">
              {t('General_Setting')}
            </div>
               <Link
                  to='/Language'
                  className="w-full bg-secondary rounded px-4 sm:px-8 py-4 flex justify-between items-center focus:outline-none focus:ring-2 focus:ring-gray-400"
                >
                  <span className="text-lg font-medium text-black">{t('Language')}</span>
                  <ChevronRight className="h-5 w-5 text-gray-600" /> 
                </Link>
          </div>
        </div>
    );
}

export default Setting;