import { useState } from 'react';
import { NavLink } from 'react-router-dom';
import { X, BookOpen, BookText, Folder, Layers, BookHeart, Users, FileArchive, FileClock, Settings } from 'lucide-react';
import LogoutButton from '../Component/LogoutButton';
import { getTokenPayload } from '../Services/getTokenPayload';
import { useLanguage } from '../Contexts/LanguageContext';
import { HeaderProvider } from '../Contexts/HeaderContext';
import Header from '../Component/Header';

const navItemsAdmin = [
  { name: 'Exercises', link: '/', icon: BookText },
  { name: 'Levels', link: '/levels', icon: Layers },
  { name: 'Matriel', link: '/matriel', icon: BookOpen },
  { name: 'Unit', link: '/unit', icon: Folder },
  { name: 'User', link: '/users', icon: Users },
  { name: 'Setting', link: '/Setting-admin', icon: Settings },
];

const navItemsUser = [
  { name: 'Exercises', link: '/user', icon: BookText },
  { name: 'Favorites_Exercise', link: '/FavoritesExercise', icon: BookHeart },
  { name: 'Current_Exam', link: '/CurrentExam', icon: FileClock },
  { name: 'Archived_Exams', link: '/ArchivedExams', icon: FileArchive },
  { name: 'Setting', link: '/Setting', icon: Settings },
];

const DashboardLayout = ({ children }) => {
  const { t } = useLanguage();
  const tokenPayload = getTokenPayload();
  const userRole = tokenPayload?.role;

  const [sidebarOpen, setSidebarOpen] = useState(false);

  const toggleSidebar = () => setSidebarOpen(!sidebarOpen);

  return (
    <HeaderProvider>
      {/* Sidebar */}
      <aside
        className={`${
          sidebarOpen ? 'translate-x-0' : '-translate-x-full'
        } fixed bg-white inset-y-0 left-0 z-50 w-64  transition-transform duration-300 ease-in-out lg:translate-x-0`}
      >
        <div className="flex h-16 items-center justify-between px-4 border-b border-secondary">
          <h2 className="text-3xl text-center text-primary font-bold w-full">{t('logoName')}</h2>
          <button onClick={toggleSidebar} className="p-2 hover:text-primary lg:hidden">
            <X className="h-6 w-6" />
          </button>
        </div>
        <nav className="mt-8 px-4">
          <ul className="space-y-2">
            {(userRole === 'admin' ? navItemsAdmin : navItemsUser).map((item) => (
              <li key={item.name}>
                <NavLink
                  to={item.link}
                  className={({ isActive }) =>
                    `btn-secondary flex items-center text-md font-semibold transition-colors duration-200 ${
                      isActive ? 'btn-secondary-active' :'' }`
                  }
                  >
                  <item.icon className="mx-3 h-5 w-5" />
                  {t(item.name)}
                </NavLink>
              </li>
            ))}
            <li>
              <LogoutButton />
            </li>
          </ul>
        </nav>
      </aside>
      <div className="lg:ml-64">
       <Header toggleSidebar={toggleSidebar} />
        {children}
      </div>
    </HeaderProvider>
  );
};

export default DashboardLayout;