import { View, Text, Image } from '@react-pdf/renderer';
import { baseURL } from '../api';
const LatexPDF = ({ content, textStyle }) => {
  const latexToPng = (latex) => {
    const encoded = encodeURIComponent(latex);
    return `${baseURL}/api/service/converter/latex/${encoded}`;
  };

  const parts = content.split(/(\$\$?.*?\$\$?)/g).filter(p => p.trim());

  return (
    <View style={{ flexDirection: 'row-reverse', alignItems: 'center', flexWrap: 'wrap' }}>
      {parts.map((part, index) => {
        const isLaTeX = part.startsWith('$') && part.endsWith('$') && part.length > 2;

        if (isLaTeX) {
          const latex = part.slice(1, -1).trim();
          if (!latex) return null;

          return (
            <Image
              key={index}
              src={latexToPng(latex)}
              style={{ 
                height: 17,
                maxWidth: 2000,
                // border:'1px solid red',
              }}
            />
          );
        }

        return (
          <Text key={index} style={[textStyle, { 
            // border:'1px solid green',
            paddingTop:'10px',
            }]}>
            {part}
          </Text>
        );
      })}
    </View>
  );
};

export default LatexPDF;