import { useState, useEffect } from 'react';
import  {Snackbar}  from '@mui/material';
import { useLanguage } from '../../Contexts/LanguageContext';
import api from '../../Services/api'
const GenralInforamtion = () => {
  const { t } = useLanguage();
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [email, setEmail] = useState('');

  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMessage, setSnackbarMessage] = useState('');
 
  useEffect(() => {
    const fetchData = async () => {
      try {
        setIsLoading(true);
        const response = await api.get(`/api/user/personal-information`);
        
        setName(response.data.name);
        setPhone(response.data.phone);
        setEmail(response.data.email);
      } catch (err) {
        setError(err.response?.data?.message || 'Something went wrong. Please try again.');
        console.log(err) 
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);
  
  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      await api.post(`/api/user/change-generale`, { name, email, phone });
      setSnackbarOpen(true);
      setSnackbarMessage('The infomation has update successfully');
    } catch (err) {
        setError(
            err.response?.data?.message || 'Something went wrong. Please try again.'
          );
    } finally {
      setIsLoading(false);
    }
  };
 

  return (
    <div className="flex justify-center items-center min-h-screen bg-gray-100 font-sans">
      <div className="bg-white p-8 rounded-lg shadow-lg w-full max-w-md">
        <h2 className="text-2xl font-bold mb-2">{t("Genral_information")}</h2>
        <form onSubmit={handleSubmit} className="space-y-4 flex flex-col">
          <div>
            <label htmlFor="name" className="block text-sm font-medium">
              {t("name")}
            </label>
            <input
              id="name"
              type="text"
              placeholder=" You Name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
              className="mt-1 mx-3 w-full input-primary"
            />
          </div>
          <div>
            <label htmlFor="email" className="block text-sm font-medium">
              {t("email")}
            </label>
            <input
              id="email"
              type="email"
              placeholder="m@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              className="mt-1 mx-3 w-full input-primary"
            />
          </div>
          <div>
            <label htmlFor="phone" className="block text-sm font-medium">
              {t("phone")}
            </label>
            <input
              id="phone"
              type="text"
              placeholder="876543210"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              required
              className="mt-1 mx-3 w-full input-primary"
            />
          </div>
          {(error) && (
            <div className="text-red-600 text-sm flex items-center gap-2">
              <span>{error}</span>
            </div>
          )}
          <button
            type="submit"
            disabled={isLoading}
            className={`w-3/4 mx-auto btn-primary`}
          >
            {isLoading ? t("loadingMsg") : t("save")}
          </button>
        </form>
      </div>
      <Snackbar
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'center',
        }}
        open={snackbarOpen}
        autoHideDuration={3000}
        onClose={() => setSnackbarOpen(false)}
        message={snackbarMessage}
      />
    </div>
  );
};

export default GenralInforamtion;